internal final class QYGD_CommonMainClass extends RunBaseBatch
{
    Str1260                 data;
    HcmPersonnelNumberId    employeeId;
    DialogField             dfData;
    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
    data
    #ENDMACRO

}

Method.Source:
public static ClassDescription description()
{
    return "OA报销凭证接口测试";
}

public Object dialog()
{
    DialogRunbase   dialog = super();

    dfData        = dialog.addField(extendedTypeStr(Str1260), 'Data');
    dfData.multiLine(true);

    return dialog;
}

public boolean getFromDialog()
{
    data                  = dfData.value();

    return super();
}

public boolean unpack(container _packedClass)
{
    Version     version     = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version] = _packedClass;
            break;
        default :
            return false;
    }

    return true;
}

public void run()
{
    QYGD_OAExpenseVoucherService    service = new QYGD_OAExpenseVoucherService();
    #OCCRetryCount
    setPrefix(this.caption());

    try
    {
        service.generateExpenseVoucher(FormJsonSerializer::deserializeObject(classNum(QYGD_OAExpenseHeaderContract), data));
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

static void main(Args _args)
{
    QYGD_CommonMainClass mainClass;
    ;

    mainClass = new QYGD_CommonMainClass();
    if (mainClass.prompt())
    {
        mainClass.run();
    }
}
